        int count = 0;
        for (Socket socket : clients) {
            if (socket.isConnected()) {
                try (PrintStream out = new PrintStream(socket.getOutputStream(), true)) {
                    out.println(message);
                    count++;
                } catch (IOException e) {
                    logger.error("Error sending message to client", e);
                }
            }
        }
        if (count == 0) {
            logger.warn("No clients available to send the message");
        }
    }

